package ch.bbw.zork;/** * Class Command - Part of the "Zork" game. * * Ein Befehl des Spielers mit einem Befehlswort und optional einem zweiten * Wort, zum Beispiel {@code buy lockpick}. Das Objekt wird vom * {@link Parser} erzeugt. Ein unbekannter Befehl hat kein Befehlswort. * * author: Michael Kolling version: 1.0 date: July 1999 * refactoring: Rinaldo Lanza, September 2020 */public class Command {	private String commandWord;	private String secondWord;	/**	 * Erstellt einen Befehl ohne zweites Wort.	 *	 * @param commandWord das Befehlswort, oder {@code null} bei einem	 *                    unbekannten Befehl	 */	public Command(String commandWord) {		this(commandWord, null);	}	public Command(String commandWord, String secondWord) {		this.commandWord = commandWord;		this.secondWord = secondWord;	}	/**	 * Liefert das Befehlswort.	 *	 * @return das Befehlswort, oder {@code null} bei einem unbekannten	 *         Befehl	 */	public String getCommandWord() {		return commandWord;	}	/**	 * Liefert das zweite Wort des Befehls.	 *	 * @return das zweite Wort, oder {@code null}, wenn es keines gibt	 */	public String getSecondWord() {		return secondWord;	}	/**	 * Prüft, ob der Befehl unbekannt ist.	 *	 * @return {@code true}, wenn kein gültiges Befehlswort vorhanden ist	 */	public boolean isUnknown() {		return (commandWord == null);	}	/**	 * Prüft, ob der Befehl ein zweites Wort hat.	 *	 * @return {@code true}, wenn ein zweites Wort vorhanden ist	 */	public boolean hasSecondWord() {		return (secondWord != null);	}}